void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // state lives in the first texels of the buffer
    vec4 prev = texelFetch(iChannel0, ivec2(fragCoord), 0);
    float t = (ivec2(fragCoord) == ivec2(0, 0)) ? iTime : prev.x;
    fragColor = vec4(t, fragCoord.y, 0., 1.);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 p = ivec2(fragCoord);
    ivec2 size = textureSize(iChannel1, 0);
    vec4 state = texelFetch(iChannel0, ivec2(0, 0), 0);
    vec4 tex = texelFetch(iChannel1, p % size, 0);
    vec3 grey = vec3(tex.x);
    fragColor = vec4(grey * state.x, 1.);
}
